 17	/// Why a replacement-routed life change could not complete synchronously.
 18	///
 19	/// Typed so phase-transition owners can distinguish the replacement-ordering
 20	/// round trip from a substitute effect that has already begun resolving and
 21	/// paused on its own interactive continuation.
 22	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 23	pub enum ReplacementDeferred {
 24	    ReplacementChoice,
 25	    SubstitutionContinuation,
 26	}
 27	
 28	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 29	enum SubstitutionDrainOutcome {
 30	    Completed,
 31	    Deferred,
 32	}
 33	
 34	/// CR 119.1: Gain life — increase the player's life total.
 35	pub fn resolve_gain(
 36	    state: &mut GameState,
 37	    ability: &ResolvedAbility,
 38	    events: &mut Vec<GameEvent>,
 39	) -> Result<(), EffectError> {
 40	    let (amount, player_filter) = match &ability.effect {
 41	        Effect::GainLife { amount, player } => (amount, player),
 42	        _ => return Err(EffectError::MissingParam("GainLife amount".to_string())),
 43	    };
 44	
 45	    // CR 119.3: Who gains the life. `resolve_life_loss_target` is the single
 46	    // authority for player resolution from a TargetFilter — context-refs
 47	    // (Controller, ParentTargetController) resolve via state slots; explicit
 48	    // Player targets come from `ability.targets`.
 49	    let player_id: PlayerId = resolve_life_loss_target(state, ability, Some(player_filter));
 50	
 51	    // CR 119.7: "If an effect says that a player can't gain life ... a replacement
 52	    // effect that would replace a life gain event affecting that player won't do
 53	    // anything." Short-circuit BEFORE the replacement pipeline.
 54	    if crate::game::static_abilities::player_has_cant_gain_life(state, player_id) {
 55	        events.push(GameEvent::EffectResolved {
 56	            kind: EffectKind::from(&ability.effect),
 57	            source_id: ability.source_id,
 58	            subject: None,
 59	        });
 60	        return Ok(());
 61	    }
 62	
 63	    let final_amount = resolve_quantity_with_targets(state, amount, ability);
 64	
 65	    if final_amount <= 0 {
 66	        events.push(GameEvent::EffectResolved {
 67	            kind: EffectKind::from(&ability.effect),
 68	            source_id: ability.source_id,
 69	            subject: None,
 70	        });
 71	        return Ok(());
 72	    }
 73	
 74	    let proposed = ProposedEvent::LifeGain {
 75	        player_id,
 76	        amount: final_amount as u32,
 77	        applied: HashSet::new(),
 78	    };
 79	
 80	    // CR 614.1a: Route life gain through replacement pipeline.
 81	    match replacement::replace_event(state, proposed, events) {
 82	        ReplacementResult::Execute(event) => {
 83	            apply_life_gain_after_replacement(state, event, events);
 84	        }
 85	        ReplacementResult::Prevented => {
 86	            // CR 614.1a + CR 614.6 — Issue #317: Cross-event-type
 87	            // substitution ("If you would gain life, draw that many cards
 88	            // instead" — Lich). The applier returned `Prevented` and stashed
 89	            // the substitute effect (e.g., Draw) as a post-replacement
 90	            // continuation. Drain it now so the replacement actually
 91	            // runs in the same resolution step.
 92	            if matches!(
 93	                drain_substitution_continuation(state, events),
 94	                SubstitutionDrainOutcome::Deferred
 95	            ) {
 96	                return Ok(());
 97	            }
 98	        }
 99	        ReplacementResult::NeedsChoice(player) => {
