119	/// Apply life gain, running through the replacement pipeline.
120	/// Returns the actual amount of life gained (may differ due to replacements like Leyline of Hope).
121	/// Returns `Err(ReplacementDeferred)` when multiple replacement effects compete and
122	/// the player must choose which applies first (CR 616.1).
123	pub fn apply_life_gain(
124	    state: &mut GameState,
125	    player_id: PlayerId,
126	    amount: u32,
127	    events: &mut Vec<GameEvent>,
128	) -> Result<u32, ReplacementDeferred> {
129	    if amount == 0 {
130	        return Ok(0);
131	    }
132	    // CR 119.7: Short-circuit BEFORE the replacement pipeline — "can't gain life"
133	    // suppresses the life gain event entirely (and any replacements that would
134	    // otherwise modify it).
135	    if crate::game::static_abilities::player_has_cant_gain_life(state, player_id) {
136	        return Ok(0);
137	    }
138	    let proposed = ProposedEvent::LifeGain {
139	        player_id,
140	        amount,
141	        applied: HashSet::new(),
142	    };
143	    match replacement::replace_event(state, proposed, events) {
144	        ReplacementResult::Execute(event) => {
145	            let gained = apply_life_gain_after_replacement(state, event, events);
146	            // CR 614.6 + CR 704.3: Drain any mandatory-post-effect continuation
147	            // (cross-event substitutes such as Lich; same-event work beyond the
148	            // applier's amount substitution) inside this resolution step so
149	            // SBAs and priority never fall between the (possibly substituted)
150	            // life gain and its substitute. Mirrors the drain pattern in
151	            // `effects/draw.rs::draw_through_replacement`. The `Prevented` arm
152	            // below already drains via `drain_substitution_continuation`.
153	            match drain_substitution_continuation(state, events) {
154	                SubstitutionDrainOutcome::Completed => Ok(gained),
155	                SubstitutionDrainOutcome::Deferred => {
156	                    Err(ReplacementDeferred::SubstitutionContinuation)
157	                }
158	            }
159	        }
160	        ReplacementResult::Prevented => {
161	            // CR 614.1a + CR 614.6 — Issue #317: Drain substitute effect
162	            // stashed by cross-event-type replacement (Lich-class).
163	            match drain_substitution_continuation(state, events) {
164	                SubstitutionDrainOutcome::Completed => Ok(0),
165	                SubstitutionDrainOutcome::Deferred => {
166	                    Err(ReplacementDeferred::SubstitutionContinuation)
167	                }
168	            }
169	        }
170	        ReplacementResult::NeedsChoice(player) => {
171	            // CR 616.1: Multiple competing replacements — player must choose.
172	            state.waiting_for =
173	                crate::game::replacement::replacement_choice_waiting_for(player, state);
174	            Err(ReplacementDeferred::ReplacementChoice)
175	        }
176	    }
177	}
