179	/// CR 614.1a + CR 614.6 — Issue #317: Drain a `post_replacement_continuation`
180	/// stashed by cross-event-type substitution in a life-gain or life-loss
181	/// replacement. Mirrors the drain points in `engine.rs` (land plays) and
182	/// `stack.rs` (stack resolution); life-change events have no natural drain
183	/// site otherwise, so the substitute effect ("draw that many cards instead",
184	/// Lich) would silently never run.
185	///
186	/// `EventContextAmount` in the substitute reads `state.last_effect_count`
187	/// (CR 615.5 fallback path), which the applier stamps with the prevented
188	/// amount before returning.
189	fn drain_substitution_continuation(
190	    state: &mut GameState,
191	    events: &mut Vec<GameEvent>,
192	) -> SubstitutionDrainOutcome {
193	    if !state.has_post_replacement_drain() {
194	        return SubstitutionDrainOutcome::Completed;
195	    }
196	
197	    // A life payment and several other production callers enter this authority
198	    // while their own prompt is still the ambient `waiting_for`. That prompt is
199	    // not evidence that the replacement continuation deferred. Run the
200	    // substitute from a clean synchronous sentinel, then restore the caller's
201	    // prompt only when the substitute itself completed without raising one.
202	    let prior_waiting_for = std::mem::replace(
203	        &mut state.waiting_for,
204	        WaitingFor::Priority {
205	            player: state.active_player,
206	        },
207	    );
208	    if let Some(waiting_for) =
209	        crate::game::engine_replacement::apply_pending_post_replacement_effect(
210	            state, None, None, None, events,
211	        )
212	    {
213	        state.waiting_for = waiting_for;
214	        SubstitutionDrainOutcome::Deferred
215	    } else {
216	        state.waiting_for = prior_waiting_for;
217	        SubstitutionDrainOutcome::Completed
218	    }
219	}
