  39	/// CR 603.2 + CR 704.3: Full trigger/SBA loop after combat damage.
  40	///
  41	/// 1. Collect triggers from damage events while source creatures are still on the battlefield
  42	///    (e.g., DamageReceived for Jackal Pup).
  43	/// 2. Run SBAs (destroy lethal-damage creatures → ZoneChanged events).
  44	/// 3. Process triggers from SBA-generated events (e.g., dies triggers from graveyard scan).
  45	/// 4. Repeat SBA/trigger cycle until stable (no new SBAs, no new triggers).
  46	fn process_combat_damage_triggers(
  47	    state: &mut GameState,
  48	    damage_events: &[GameEvent],
  49	    all_events: &mut Vec<GameEvent>,
  50	    include_phase_event: bool,
  51	) {
  52	    // Step 1: Collect triggers from damage events while creatures are still alive.
  53	    // CR 603.2: Triggers fire at the moment the event occurs — process_triggers
  54	    // scans state.battlefield, so this must run before SBAs remove dying objects.
  55	    let mut before_priority_events = Vec::new();
  56	    if include_phase_event {
  57	        before_priority_events.push(GameEvent::PhaseChanged {
  58	            phase: crate::types::phase::Phase::CombatDamage,
  59	        });
  60	    }
  61	    before_priority_events.extend_from_slice(damage_events);
  62	    let mut pending = triggers::collect_triggers_for_batch(state, &before_priority_events);
  63	
  64	    // Steps 2-4: SBA/trigger loop per CR 704.3.
  65	    // SBAs may generate events (ZoneChanged for dying creatures) that need trigger
  66	    // processing (dies triggers). Repeat until no new SBAs and no new triggers.
  67	    loop {
  68	        let events_before = all_events.len();
  69	        sba::check_state_based_actions(state, all_events);
  70	
  71	        // If SBAs generated new events, process triggers for those events.
  72	        if all_events.len() > events_before {
  73	            let new_events: Vec<_> = all_events[events_before..].to_vec();
  74	            before_priority_events.extend_from_slice(&new_events);
  75	            pending.extend(triggers::collect_triggers_for_batch(state, &new_events));
  76	        } else {
  77	            break;
  78	        }
  79	    }
  80	
  81	    if matches!(
  82	        state.waiting_for,
  83	        crate::types::game_state::WaitingFor::GameOver { .. }
  84	    ) {
  85	        return;
  86	    }
  87	    // CR 800.4a: If combat-damage SBAs eliminated a player before this
  88	    // collect-only batch is put on the stack, drop triggers controlled by that
  89	    // player before constructing the APNAP ordering pass.
  90	    pending.retain(|ctx| crate::game::players::is_alive(state, ctx.pending.controller));
  91	
  92	    triggers::process_collected_triggers_with_delayed_events(
  93	        state,
  94	        pending,
  95	        &before_priority_events,
  96	        all_events,
  97	    );
  98	}
