 100	/// Resolve combat damage with first strike / double strike support (CR 510.1).
 101	/// CR 702.7b: If any creature has first strike or double strike, two damage sub-steps run.
 102	/// Between sub-steps: SBAs are checked and triggers processed.
 103	///
 104	/// Returns `Some(WaitingFor)` when an attacker with 2+ blockers needs interactive
 105	/// damage assignment. Returns `None` when all damage for the current phase is resolved.
 106	/// Re-entrant: call again after the player submits `GameAction::AssignCombatDamage`.
 107	pub fn resolve_combat_damage(
 108	    state: &mut GameState,
 109	    events: &mut Vec<GameEvent>,
 110	) -> Option<WaitingFor> {
 111	    // CR 510.2 + CR 616.1: a parked batch still owns this turn-based action and
 112	    // its damage is ALREADY dealt (the batch is one event and must never be
 113	    // replayed). Placed AHEAD of `state.combat.as_ref()?` so no combat teardown
 114	    // can strand the record behind that `?`.
 115	    if state.pending_combat_lifelink.is_some() {
 116	        // Any live prompt — the CR 616.1 ordering choice itself, or a sub-choice
 117	        // raised while answering it — means an answer is still coming. Surface it
 118	        // rather than re-collecting assignments. The `matches!` below has already
 119	        // excluded `Priority`, so what is returned is always a genuine prompt;
 120	        // `resolve_combat_damage`'s contract never yields a bare `Priority`.
 121	        if !matches!(state.waiting_for, WaitingFor::Priority { .. }) {
 122	            return Some(state.waiting_for.clone());
 123	        }
 124	        // Settled to priority with a batch still parked. Either the seat that
 125	        // owed the CR 616.1 answer left the game (CR 800.4a: `elimination` cleared
 126	        // `pending_replacement` and the reconcile wrote `Priority { next }`), or a
 127	        // sub-choice of the answer resolved through a dispatcher other than
 128	        // `handle_replacement_choice`. No further `ChooseReplacement` will arrive,
 129	        // so finish the batch here — otherwise the owed gains die with combat AND
 130	        // the `!regular_damage_done` completeness gate (priority.rs) re-enters
 131	        // this function forever.
 132	        //
 133	        // `events.len()` folds nothing: no answering action's events are in
 134	        // flight on this path.
 135	        return resume_pending_combat_lifelink(state, events.len(), events);
 136	    }
 137	
 138	    let combat = state.combat.as_ref()?.clone();
 139	
 140	    // Guard: regular damage already applied (re-entry from triggers during regular step).
 141	    if combat.regular_damage_done {
 142	        return None;
 143	    }
 144	
 145	    let first_strike_participants = combat
 146	        .first_strike_participants
 147	        .clone()
 148	        .unwrap_or_else(|| combat_first_strike_participants(state, &combat));
 149	    if combat.first_strike_participants.is_none() {
 150	        if let Some(current) = state.combat.as_mut() {
 151	            current.first_strike_participants = Some(first_strike_participants.clone());
 152	        }
 153	    }
 154	    let has_first_or_double = !first_strike_participants.is_empty();
 155	
 156	    // --- First strike sub-step ---
 157	    if has_first_or_double && !combat.first_strike_done {
 158	        if let Some(waiting) = collect_damage_assignments(state, CombatDamageSubStep::FirstStrike) {
 159	            return Some(waiting);
 160	        }
 161	        // All first-strike assignments collected — apply simultaneously (CR 510.2).
 162	        let pending = take_pending_damage(state);
 163	        let batch = apply_combat_damage(state, &pending, CombatDamageSubStep::FirstStrike);
 164	        let batch_event_start = events.len();
 165	        events.extend_from_slice(batch.events());
 166	        match batch {
 167	            // CR 616.1: the batch parked on a life-gain ordering choice. The
 168	            // sub-step flags are deliberately NOT set here — the resume sets them
 169	            // once the batch actually completes, so neither re-entry nor
 170	            // priority.rs's completeness gate can skip the rest of combat damage.
 171	            CombatDamageBatch::Paused { waiting_for, .. } => {
 172	                claim_combat_lifelink_batch_events_for_ordinary_collection(
 173	                    state,
 174	                    events,
 175	                    batch_event_start,
 176	                );
 177	                return Some(*waiting_for);
 178	            }
 179	            CombatDamageBatch::Complete(damage_events) => {
 180	                if let Some(wf) = finish_combat_damage_sub_step(
 181	                    state,
 182	                    CombatDamageSubStep::FirstStrike,
 183	                    &damage_events,
 184	                    events,
 185	                ) {
 186	                    return Some(wf);
 187	                }
 188	            }
 189	        }
 190	    }
 191	
 192	    // --- Regular damage sub-step ---
 193	    if let Some(waiting) = collect_damage_assignments(state, CombatDamageSubStep::Regular) {
 194	        return Some(waiting);
 195	    }
 196	    // All regular assignments collected — apply simultaneously (CR 510.2).
 197	    let pending = take_pending_damage(state);
 198	    let batch = apply_combat_damage(state, &pending, CombatDamageSubStep::Regular);
 199	    let batch_event_start = events.len();
 200	    events.extend_from_slice(batch.events());
 201	    match batch {
 202	        // CR 616.1: see the first-strike arm above — the completion flags belong
 203	        // to the resume, not to a batch that has parked.
 204	        CombatDamageBatch::Paused { waiting_for, .. } => {
 205	            claim_combat_lifelink_batch_events_for_ordinary_collection(
 206	                state,
 207	                events,
 208	                batch_event_start,
 209	            );
 210	            Some(*waiting_for)
 211	        }
 212	        CombatDamageBatch::Complete(damage_events) => finish_combat_damage_sub_step(
 213	            state,
 214	            CombatDamageSubStep::Regular,
 215	            &damage_events,
 216	            events,
 217	        ),
 218	    }
 219	}
