 221	/// CR 510.2 + CR 510.4 + CR 603.2 + CR 704.3: everything that must happen once
 222	/// ONE simultaneous combat-damage batch is fully applied — sub-step bookkeeping,
 223	/// the trigger/SBA loop, and the sub-step's own completion states.
 224	///
 225	/// Shared by the inline path and the CR 616.1 resume so the two cannot drift.
 226	fn finish_combat_damage_sub_step(
 227	    state: &mut GameState,
 228	    sub_step: CombatDamageSubStep,
 229	    damage_events: &[GameEvent],
 230	    events: &mut Vec<GameEvent>,
 231	) -> Option<WaitingFor> {
 232	    // CR 500.6: "at the beginning of that step" abilities trigger when the step
 233	    // begins. `process_combat_damage_triggers` synthesizes the PhaseChanged
 234	    // marker for that batch, so the FIRST-STRIKE sub-step always carries it, and
 235	    // the regular sub-step carries it only when it is the ONLY sub-step.
 236	    //
 237	    // Reproduces the previous `!combat.first_strike_done && !has_first_or_double`,
 238	    // which read the entry-time clone. Evaluated BEFORE the `regular_damage_done`
 239	    // write. Equivalent for all three reachable entry states:
 240	    //   * no first strike, single sub-step               -> true  (== old true)
 241	    //   * first-strike sub-step ran earlier in THIS call -> first_strike_done -> false
 242	    //   * re-entry after a prior call's first strike     -> first_strike_done -> false
 243	    let include_phase_event = match sub_step {
 244	        CombatDamageSubStep::FirstStrike => true,
 245	        CombatDamageSubStep::Regular => state.combat.as_ref().is_some_and(|c| {
 246	            !c.first_strike_done
 247	                && c.first_strike_participants
 248	                    .as_ref()
 249	                    .is_none_or(|participants| participants.is_empty())
 250	        }),
 251	    };
 252	
 253	    match sub_step {
 254	        CombatDamageSubStep::FirstStrike => {
 255	            if let Some(c) = &mut state.combat {
 256	                c.first_strike_done = true;
 257	                c.damage_step_index = None;
 258	                // CR 510.4: The regular combat-damage sub-step is a fresh assignment.
 259	                // `damage_assignments` is the per-sub-step blocker resume-skip key
 260	                // (CR 702.22k / CR 510.1d), so it MUST be reset between sub-steps —
 261	                // otherwise a double-strike blocker that divided its first-strike
 262	                // damage would be wrongly skipped in the regular sub-step.
 263	                c.damage_assignments.clear();
 264	            }
 265	
 266	            // CR 510.4: SBAs and triggers run between first-strike and regular damage sub-steps.
 267	            process_combat_damage_triggers(state, damage_events, events, include_phase_event);
 268	
 269	            // CR 510.4 + CR 603.3b: if the first-strike sub-step produced a same-
 270	            // controller trigger-ordering prompt, surface it now — before the regular
 271	            // sub-step's own trigger processing clobbers/orphans it. Returning here
 272	            // leaves `regular_damage_done == false`; the mandatory second (regular)
 273	            // combat-damage sub-step is resumed by the priority-pass completeness gate
 274	            // in priority.rs, which re-enters this function once the order is submitted
 275	            // and the resulting triggers resolve.
 276	            if let Some(waiting_for) = pending_combat_damage_waiting(state) {
 277	                return Some(waiting_for);
 278	            }
 279	
 280	            // CR 510.3 + CR 510.3a + CR 510.4: The first-strike combat-damage step is a
 281	            // complete step. Abilities that triggered on first-strike damage (or on SBAs
 282	            // taken afterward) are put on the stack, and THEN the active player receives
 283	            // priority — players must finish with the stack before the second (regular)
 284	            // combat-damage sub-step begins. If the first-strike sub-step placed anything
 285	            // on the stack (e.g. No Mercy's "destroy that creature", a damage trigger that
 286	            // bounces/exiles the attacker), grant priority now so that object resolves
 287	            // first. Skipping this would let a now-doomed double-strike attacker deal its
 288	            // regular-sub-step damage before the trigger that removes it resolves (#692).
 289	            // Returning here leaves `regular_damage_done == false`; the mandatory regular
 290	            // sub-step is resumed once the stack drains and all players pass, via the
 291	            // empty-stack completeness gate in priority.rs.
 292	            if !state.stack.is_empty() {
 293	                // reset_priority here is defensive — unlike the sibling regular-substep entry in
 294	                // turns.rs, this returns mid-step after the first-strike substep, so we explicitly
 295	                // clear any stale passes before the CR 510.3 priority window (harmless if already clear).
 296	                crate::game::priority::reset_priority(state);
 297	                return Some(WaitingFor::Priority {
 298	                    player: state.active_player,
 299	                });
 300	            }
 301	            None
 302	        }
 303	        CombatDamageSubStep::Regular => {
 304	            if let Some(c) = &mut state.combat {
 305	                c.regular_damage_done = true;
 306	                c.damage_step_index = None;
 307	            }
 308	
 309	            process_combat_damage_triggers(state, damage_events, events, include_phase_event);
 310	            pending_combat_damage_waiting(state)
 311	        }
 312	    }
 313	}
