 315	/// CR 616.1 + CR 510.2 + CR 702.15b: finish a combat-damage batch that parked on
 316	/// a lifelink life-gain ordering choice.
 317	///
 318	/// `action_event_start` is the index at which the ANSWERING action's events
 319	/// begin. It is a parameter, never stored: `handle_replacement_choice` captures
 320	/// it as a local before the answer is applied, and the re-entry guard passes
 321	/// `events.len()` when no answer is in flight. Both are `<= events.len()` by
 322	/// construction, so the slice below cannot be out of range.
 323	///
 324	/// The answering action's events — the resumed `LifeChanged` among them — are
 325	/// folded into the parked batch, so "whenever you gain life" observers
 326	/// (CR 119.9) join the SAME CR 603.3b batch as the combat-damage observers.
 327	/// CR 702.15b makes the gain simultaneous with the damage, and no player
 328	/// received priority for the CR 616.1 choice, so splitting them would be a rules
 329	/// regression.
 330	///
 331	/// Returns `None` when nothing is parked, so callers can keep their own wait.
 332	pub(crate) fn resume_pending_combat_lifelink(
 333	    state: &mut GameState,
 334	    action_event_start: usize,
 335	    events: &mut Vec<GameEvent>,
 336	) -> Option<WaitingFor> {
 337	    let mut record = *state.pending_combat_lifelink.take()?;
 338	    record
 339	        .batch_events
 340	        .extend_from_slice(&events[action_event_start..]);
 341	    let owed_from = record.batch_events.len();
 342	    let sub_step = record.sub_step;
 343	    match drain_combat_lifelink(state, record) {
 344	        CombatDamageBatch::Paused {
 345	            events: batch,
 346	            waiting_for,
 347	        } => {
 348	            // CR 616.1f: a LATER source needed its own ordering choice. The
 349	            // still-untouched tail was re-parked with the batch so far, so the
 350	            // eventual completion still fires ONE CR 603.3b batch.
 351	            events.extend_from_slice(&batch[owed_from..]);
 352	            claim_combat_lifelink_batch_events_for_ordinary_collection(
 353	                state,
 354	                events,
 355	                action_event_start,
 356	            );
 357	            Some(*waiting_for)
 358	        }
 359	        CombatDamageBatch::Complete(damage_events) => {
 360	            events.extend_from_slice(&damage_events[owed_from..]);
 361	            let waiting_for =
 362	                finish_combat_damage_sub_step(state, sub_step, &damage_events, events);
 363	            claim_combat_lifelink_batch_events_for_ordinary_collection(
 364	                state,
 365	                events,
 366	                action_event_start,
 367	            );
 368	            if let Some(wf) = waiting_for {
 369	                return Some(wf);
 370	            }
 371	            // CR 510.4: the second combat damage step is MANDATORY. Re-enter so a
 372	            // paused first-strike batch still runs it, exactly as the inline path
 373	            // does. Bounded: the record was `.take()`n above, so the re-entry
 374	            // guard cannot route back here; a regular sub-step that parks returns
 375	            // its own prompt without recursing, and a regular sub-step already
 376	            // done short-circuits on `regular_damage_done`.
 377	            resolve_combat_damage(state, events).or(Some(WaitingFor::Priority {
 378	                player: state.active_player,
 379	            }))
 380	        }
 381	    }
 382	}
