 384	/// CR 510.2 + CR 603.2c: a combat-damage batch parked for a CR 616.1 choice
 385	/// still owns its ordinary trigger collection. Suppress only the generic
 386	/// post-action ordinary collector for the exact full-buffer occurrences; the
 387	/// resumed batch collector receives the retained events, and delayed collectors
 388	/// retain their CR 603.7b visibility.
 389	fn claim_combat_lifelink_batch_events_for_ordinary_collection(
 390	    state: &mut GameState,
 391	    events: &[GameEvent],
 392	    event_start: usize,
 393	) {
 394	    let occurrences = (event_start..events.len())
 395	        .map(|index| triggers::ConsumedTriggerEventOccurrence {
 396	            event: events[index].clone(),
 397	            occurrence: triggers::trigger_event_occurrence(events, index),
 398	            scope: triggers::ConsumedTriggerEventScope::OrdinaryCollectorsOnly,
 399	        })
 400	        .collect();
 401	    triggers::resolve_and_apply_trigger_collection(
 402	        state,
 403	        crate::types::resolved_commands::ResolvedTriggerCollection::ConsumeBeforePriority {
 404	            occurrences,
 405	        },
 406	    )
 407	    .expect("combat lifelink ordinary trigger claim must have a live journal cause");
 408	}
