 410	/// Returns a terminal or trigger-ordering state produced while combat damage resolves.
 411	///
 412	/// CR 603.3b / CR 704.3: trigger ordering and game-over results are completion
 413	/// states of the combat-damage resolver, so callers must receive them rather than
 414	/// replacing them with a fresh priority window.
 415	fn pending_combat_damage_waiting(state: &GameState) -> Option<WaitingFor> {
 416	    match &state.waiting_for {
 417	        WaitingFor::OrderTriggers { .. } | WaitingFor::GameOver { .. } => {
 418	            Some(state.waiting_for.clone())
 419	        }
 420	        _ => None,
 421	    }
 422	}
