 424	fn combat_first_strike_participants(
 425	    state: &GameState,
 426	    combat: &CombatState,
 427	) -> std::collections::HashSet<ObjectId> {
 428	    combat
 429	        .attackers
 430	        .iter()
 431	        .map(|attacker| attacker.object_id)
 432	        .chain(combat.blocker_to_attacker.keys().copied())
 433	        .filter(|object_id| {
 434	            state.objects.get(object_id).is_some_and(|object| {
 435	                object.has_keyword(&Keyword::FirstStrike)
 436	                    || object.has_keyword(&Keyword::DoubleStrike)
 437	            })
 438	        })
 439	        .collect()
 440	}
