 442	fn deals_in_substep(
 443	    obj: &GameObject,
 444	    sub_step: CombatDamageSubStep,
 445	    first_strike_participants: &std::collections::HashSet<ObjectId>,
 446	) -> bool {
 447	    match sub_step {
 448	        CombatDamageSubStep::FirstStrike => first_strike_participants.contains(&obj.id),
 449	        CombatDamageSubStep::Regular => {
 450	            !first_strike_participants.contains(&obj.id) || obj.has_keyword(&Keyword::DoubleStrike)
 451	        }
 452	    }
 453	}
