  22	/// CR 510.1a + CR 613.11: Returns the amount of combat damage a creature assigns.
  23	/// Normally equal to power, but if `assigns_damage_from_toughness` is set (e.g. Doran),
  24	/// uses toughness instead. If `assigns_no_combat_damage` is set, returns 0.
  25	fn combat_damage_amount(obj: &GameObject) -> u32 {
  26	    // CR 510.1a: "~ assigns no combat damage" — creature deals 0 combat damage.
  27	    if obj.assigns_no_combat_damage {
  28	        return 0;
  29	    }
  30	    if obj.assigns_damage_from_toughness {
  31	        // CR 613.11 + CR 510.1a: Rule effect uses toughness rather than power.
  32	        obj.toughness.unwrap_or(0).max(0) as u32
  33	    } else {
  34	        // CR 510.1a: Assign combat damage equal to power.
  35	        obj.power.unwrap_or(0).max(0) as u32
  36	    }
  37	}
