1526	impl CombatDamageBatch {
1527	    /// The batch's events so far, for the caller's running event log.
1528	    fn events(&self) -> &[GameEvent] {
1529	        match self {
1530	            Self::Complete(events) | Self::Paused { events, .. } => events,
1531	        }
1532	    }
1533	}
