2337	    /// Drive `resolve_combat_damage` and, whenever it pauses on an
2338	    /// `AssignCombatDamage` prompt (now reachable for single-blocker trample with
2339	    /// excess per CR 702.19b, as well as the existing 2+ blocker case), submit the
2340	    /// canonical greedy split through the real apply path: lethal to each blocker
2341	    /// in order, then trample the remainder to the attack target (splitting
2342	    /// loyalty-worth to the PW and the rest to its controller for trample-over-PW).
2343	    /// This mirrors `run_combat` in the integration harness and the AI default, so
2344	    /// tests that previously relied on auto-assignment keep asserting that split.
2345	    fn resolve_combat_with_greedy_assignment(state: &mut GameState, events: &mut Vec<GameEvent>) {
2346	        if let Some(waiting) = resolve_combat_damage(state, events) {
2347	            state.waiting_for = waiting;
2348	        } else {
2349	            return;
2350	        }
2351	        while let WaitingFor::AssignCombatDamage {
2352	            attacker_id,
2353	            total_damage,
2354	            ref blockers,
2355	            ref trample,
2356	            pw_loyalty,
2357	            ref attack_target,
2358	            ..
2359	        } = state.waiting_for
2360	        {
2361	            let _ = attacker_id;
2362	            let mut remaining = total_damage;
2363	            let mut assignments: Vec<(ObjectId, u32)> = Vec::new();
2364	            for slot in blockers {
2365	                let assign = remaining.min(slot.lethal_minimum);
2366	                assignments.push((slot.blocker_id, assign));
2367	                remaining = remaining.saturating_sub(assign);
2368	            }
2369	            if trample.is_none() && remaining > 0 {
2370	                if let Some(last) = assignments.last_mut() {
2371	                    last.1 += remaining;
2372	                    remaining = 0;
2373	                }
2374	            }
2375	            let (trample_damage, controller_damage) = if *trample
2376	                == Some(TrampleKind::OverPlaneswalkers)
2377	                && matches!(attack_target, AttackTarget::Planeswalker(_))
2378	            {
2379	                let loyalty = pw_loyalty.unwrap_or(0);
2380	                let to_pw = remaining.min(loyalty);
2381	                (to_pw, remaining.saturating_sub(to_pw))
2382	            } else {
2383	                (if trample.is_some() { remaining } else { 0 }, 0)
2384	            };
