2386	                state,
2387	                crate::types::actions::GameAction::AssignCombatDamage {
2388	                    mode: CombatDamageAssignmentMode::Normal,
2389	                    assignments,
2390	                    trample_damage,
2391	                    controller_damage,
2392	                },
2393	            )
2394	            .expect("greedy combat damage assignment must be legal");
2395	        }
