2917	        setup_combat(&mut state, vec![attacker], vec![(attacker, vec![blocker])]);
2918	
2919	        // One source, two simultaneous damage assignments (2 to blocker + 3 to player).
2920	        let assignments = vec![
2921	            (
2922	                attacker,
2923	                DamageAssignment {
2924	                    target: DamageTarget::Object(blocker),
2925	                    amount: 2,
