   278	#[test]
   279	fn real_damage_spell_replays_recorded_final_life_delta() {
   280	    let (pre_state, ordinary_state) = damage_spell_states();
   281	    let commands = semantic_commands(&ordinary_state);
   282	    let life_command = commands
   283	        .iter()
   284	        .find(|command| {
   285	            matches!(
   286	                command,
   287	                ResolvedRulesCommand::PlayerEdit(ResolvedPlayerEditCommand {
   288	                    player: P1,
   289	                    edit: ResolvedPlayerEdit::Life { delta: -3 },
   290	                    ..
   291	                })
   292	            )
   293	        })
   294	        .expect("Lightning Bolt must journal its final delivered life delta");
   295	
   296	    let mut replay = pre_state;
   297	    replay.resolved_rules_journal = ordinary_state.resolved_rules_journal.clone();
   298	    apply_semantic_command(&mut replay, life_command);
   299	
   300	    let replayed = replay
   301	        .players
   302	        .iter()
   303	        .find(|player| player.id == P1)
   304	        .unwrap();
   305	    let ordinary = ordinary_state
   306	        .players
   307	        .iter()
   308	        .find(|player| player.id == P1)
   309	        .unwrap();
   310	    assert_eq!(replayed.life, ordinary.life);
