   321	fn recorded_tap_rejects_double_apply_and_stale_incarnation() {
   322	    let (pre_state, ordinary_state, signet) = activated_signet_states();
   323	    let command = semantic_commands(&ordinary_state)
   324	        .into_iter()
   325	        .find_map(|command| match command {
   326	            ResolvedRulesCommand::ObjectStatus(command) if command.object.object_id == signet => {
   327	                Some(command)
   328	            }
