   373	/// The scalar authority edits one resource axis at a time. It records semantic
   374	/// deltas/transitions instead of replacing a player snapshot, so unrelated
   375	/// retained resource edits remain intact.
   376	#[test]
   377	fn scalar_commands_compose_across_life_energy_counters_and_speed() {
   378	    let mut state = GameState::new_two_player(7);
   379	
   380	    state
   381	        .resolve_and_apply_player_edit(P0, ResolvedPlayerEdit::Life { delta: 2 })
   382	        .unwrap();
   383	    state
   384	        .resolve_and_apply_player_edit(P0, ResolvedPlayerEdit::Energy { delta: 3 })
   385	        .unwrap();
   386	    state
   387	        .resolve_and_apply_player_edit(
   388	            P0,
   389	            ResolvedPlayerEdit::Counter {
   390	                kind: PlayerCounterKind::Experience,
   391	                delta: 1,
   392	            },
   393	        )
   394	        .unwrap();
   395	    state
   396	        .resolve_and_apply_player_edit(
   397	            P0,
   398	            ResolvedPlayerEdit::Speed {
   399	                old: None,
   400	                new: Some(3),
   401	            },
   402	        )
   403	        .unwrap();
   404	
   405	    let player = state.players.iter().find(|player| player.id == P0).unwrap();
   406	    assert_eq!(player.life, 22);
   407	    assert_eq!(player.life_gained_this_turn, 2);
   408	    assert_eq!(player.energy, 3);
   409	    assert_eq!(
