 726	/// CR 122.1: Apply a final debug-selected player-counter delta through the
 727	/// same scalar authority as ordinary rules actions.
 728	fn apply_player_counter_delta(
 729	    state: &mut GameState,
 730	    player_id: PlayerId,
 731	    counter_kind: PlayerCounterKind,
 732	    delta: i32,
 733	    events: &mut Vec<GameEvent>,
 734	) {
 735	    let Some(before) = state
 736	        .players
 737	        .iter()
 738	        .find(|player| player.id == player_id)
 739	        .map(|player| player.player_counter(&counter_kind))
 740	    else {
 741	        return;
 742	    };
 743	    let after = if delta.is_positive() {
 744	        before
 745	            .checked_add(delta as u32)
 746	            .expect("debug counter addition must not overflow")
 747	    } else {
 748	        before.saturating_sub(delta.unsigned_abs())
 749	    };
 750	    let actual_delta = i32::try_from(i64::from(after) - i64::from(before))
 751	        .expect("a requested i32 counter delta must remain representable");
 752	    if actual_delta != 0 {
 753	        state
 754	            .resolve_and_apply_player_edit(
 755	                player_id,
 756	                ResolvedPlayerEdit::Counter {
 757	                    kind: counter_kind,
 758	                    delta: actual_delta,
 759	                },
 760	            )
 761	            .expect("the computed debug counter delta must satisfy its resolved precondition");
 762	        events.push(GameEvent::PlayerCounterChanged {
 763	            player: player_id,
 764	            counter_kind,
 765	            delta: actual_delta,
 766	        });
 767	    }
 768	}
