119	fn is_complete_generated_candidate(state: &GameState, candidate: &CandidateAction) -> bool {
120	    let (Some(semantic_owner), Some(actor)) =
121	        (candidate.metadata.semantic_owner, candidate.metadata.actor)
122	    else {
123	        return false;
124	    };
125	    actor == authorized_submitter_for_player(state, semantic_owner)
126	        && crate::ai_support::candidate_actions(state)
127	            .iter()
128	            .any(|emitted| {
129	                emitted.action == candidate.action
130	                    && emitted.metadata.semantic_owner == Some(semantic_owner)
131	                    && emitted.metadata.actor == Some(actor)
132	                    && emitted.metadata.tactical_class == candidate.metadata.tactical_class
133	            })
134	}
