136	fn selected_optional_life_branch(
137	    cost: &AdditionalCost,
138	    pay: bool,
139	) -> Option<(OptionalAdditionalCostBranch, AbilityCost)> {
140	    match (cost, pay) {
141	        (
142	            AdditionalCost::Optional {
143	                cost: AbilityCost::PayLife { .. },
144	                ..
145	            },
146	            true,
147	        ) => Some((
148	            OptionalAdditionalCostBranch::OptionalAccepted,
149	            match cost {
150	                AdditionalCost::Optional { cost, .. } => cost.clone(),
151	                AdditionalCost::Kicker { .. }
152	                | AdditionalCost::Choice(_, _)
153	                | AdditionalCost::Required(_) => unreachable!("matched Optional above"),
154	            },
155	        )),
156	        (AdditionalCost::Choice(preferred @ AbilityCost::PayLife { .. }, _), true) => Some((
157	            OptionalAdditionalCostBranch::ChoicePreferred,
158	            preferred.clone(),
159	        )),
160	        (AdditionalCost::Choice(_, fallback @ AbilityCost::PayLife { .. }), false) => Some((
161	            OptionalAdditionalCostBranch::ChoiceFallback,
162	            fallback.clone(),
163	        )),
164	        (AdditionalCost::Optional { .. }, false)
165	        | (AdditionalCost::Optional { .. }, true)
166	        | (AdditionalCost::Choice(_, _), true)
167	        | (AdditionalCost::Choice(_, _), false)
168	        | (AdditionalCost::Kicker { .. }, true | false)
169	        | (AdditionalCost::Required(_), true | false) => None,
170	    }
171	}
172	
173	fn optional_additional_cost_path(pending: &PendingCast) -> OptionalAdditionalCostPath {
174	    if let Some(instance) = pending.additional_cost_queue.first() {
175	        return OptionalAdditionalCostPath::Queue {
176	            origin: instance.origin,
177	            origin_ordinal: instance.origin_ordinal,
178	        };
179	    }
180	    match pending.additional_cost_flow.as_ref() {
181	        Some(AdditionalCost::Optional { repeatability, .. }) => OptionalAdditionalCostPath::Flow {
182	            repeatability: *repeatability,
183	        },
184	        Some(AdditionalCost::Kicker { .. })
185	        | Some(AdditionalCost::Choice(_, _))
186	        | Some(AdditionalCost::Required(_))
187	        | None => OptionalAdditionalCostPath::Direct,
188	    }
189	}
