191	fn extract_life_cost_root(
192	    state: &GameState,
193	    candidate: &CandidateAction,
194	) -> Option<ArmedLifeCostRoot> {
195	    let semantic_owner = candidate.metadata.semantic_owner?;
196	    if !is_complete_generated_candidate(state, candidate) {
197	        return None;
198	    }
199	
200	    match (&state.waiting_for, &candidate.action) {
201	        (
202	            WaitingFor::DefilerPayment {
203	                player,
204	                life_cost,
205	                mana_reduction,
206	                pending_cast,
207	            },
208	            GameAction::DecideOptionalCost { pay: true },
209	        ) if *player == semantic_owner => Some(ArmedLifeCostRoot::DefilerPayment(Box::new(
210	            DefilerPaymentWitness {
211	                player: *player,
212	                offered_life_cost: *life_cost,
213	                mana_reduction: mana_reduction.clone(),
214	                pending_cast: *pending_cast.clone(),
215	                candidate: candidate.clone(),
216	            },
217	        ))),
218	        (
219	            WaitingFor::OptionalCostChoice {
220	                player,
221	                cost,
222	                times_kicked,
223	                origin,
224	                gift_kind,
225	                pending_cast,
226	            },
227	            GameAction::DecideOptionalCost { pay },
228	        ) if *player == semantic_owner => {
229	            let (branch, materialized_cost) = selected_optional_life_branch(cost, *pay)?;
230	            let path = optional_additional_cost_path(pending_cast);
231	            Some(ArmedLifeCostRoot::OptionalAdditionalCost(Box::new(
232	                OptionalAdditionalCostWitness {
233	                    player: *player,
234	                    cost: cost.clone(),
235	                    times_kicked: *times_kicked,
236	                    origin: *origin,
237	                    gift_kind: gift_kind.clone(),
238	                    pending_cast: *pending_cast.clone(),
239	                    candidate: candidate.clone(),
240	                    branch,
241	                    materialized_cost,
242	                    path,
243	                },
244	            )))
245	        }
246	        // CombatTaxPayment / PayCombatTax, raw mana payment, and all other
247	        // mechanical choices are deliberately neutral. CR 508.1d / 509.1c
248	        // combat costs are declaration decisions, not cast/activation costs.
249	        _ => None,
250	    }
251	}
