253	/// Preview a generated candidate through the raw reducer boundary.
254	///
255	/// CR 118.3b + CR 119.4: a life payment is decided by the actual team-life
256	/// mutation, not by the requested cost or a later event summary. Any route
257	/// without one exact, positive post-replacement receipt remains neutral.
258	pub fn preview_candidate_life_safety(
259	    state: &GameState,
260	    candidate: &CandidateAction,
261	) -> CandidateLifeSafety {
262	    let Some(root) = extract_life_cost_root(state, candidate) else {
263	        return CandidateLifeSafety::NotUnsafe;
264	    };
265	
266	    let mut preview = state.clone();
267	    preview.life_safety_probe.arm(root);
268	    observe_boundary_carrier(&mut preview);
269	    let applied = engine::apply_interaction_pre_reconciliation_for_life_safety(
270	        &mut preview,
271	        candidate.metadata.actor.expect("validated above"),
272	        candidate.metadata.semantic_owner.expect("validated above"),
273	        candidate.action.clone(),
274	    );
275	    if applied.is_err() {
276	        return CandidateLifeSafety::NotUnsafe;
277	    }
278	
279	    observe_boundary_carrier(&mut preview);
280	    preview.life_safety_probe.take_lethal_receipt()
281	}
282	
283	/// Marks work that can carry a raw reducer action beyond its direct payment
284	/// seam. The preview never converts such a route into a positive result: only
285	/// an already-bound post-replacement receipt can produce `Unsafe`.
286	pub(crate) fn observe_boundary_carrier(state: &mut GameState) {
287	    let allowed_root_waiting = matches!(
288	        state.waiting_for,
289	        WaitingFor::OptionalCostChoice { .. } | WaitingFor::DefilerPayment { .. }
290	    );
291	    let has_carrier = (!allowed_root_waiting
292	        && !matches!(state.waiting_for, WaitingFor::Priority { .. }))
293	        || !state.resolution_stack.is_empty()
294	        || state.pending_resolution_completion.is_some()
295	        || state.pending_deferred_life_cost_resume.is_some()
296	        || state.pending_cost_move_resume.is_some()
297	        || state.pending_replacement.is_some()
298	        || state.pending_trigger.is_some()
299	        || !state.pending_trigger_event_batch.is_empty()
300	        || state.pending_trigger_entry.is_some()
301	        || state.pending_trigger_order.is_some()
302	        || state.pending_scoped_library_search.is_some()
303	        || state.pending_library_search_delivery.is_some();
304	    if has_carrier && state.life_safety_probe.armed_root.is_some() {
305	        state.life_safety_probe.carrier_observed = true;
306	    }
307	}
