309	impl LifeSafetyProbe {
310	    fn arm(&mut self, root: ArmedLifeCostRoot) {
311	        self.armed_root = Some(root);
312	        self.attempt = Some(AttemptState::Idle);
313	        self.receipt = None;
314	        self.carrier_observed = false;
315	    }
316	
317	    fn take_lethal_receipt(&mut self) -> CandidateLifeSafety {
318	        let receipt = self.receipt.take();
319	        let armed_payer = match &self.armed_root {
320	            Some(ArmedLifeCostRoot::DefilerPayment(witness)) => witness.player,
321	            Some(ArmedLifeCostRoot::OptionalAdditionalCost(witness)) => witness.player,
322	            None => return CandidateLifeSafety::NotUnsafe,
323	        };
324	        self.armed_root = None;
325	        self.attempt = None;
326	        let carrier_observed = self.carrier_observed;
327	        self.carrier_observed = false;
328	        if carrier_observed && receipt.is_none() {
329	            return CandidateLifeSafety::NotUnsafe;
330	        }
331	        match receipt {
332	            Some(receipt)
333	                if receipt.token != 0 && receipt.payer == armed_payer && receipt.after <= 0 =>
334	            {
335	                CandidateLifeSafety::Unsafe {
336	                    before: receipt.before,
337	                    after: receipt.after,
338	                    committed: receipt.committed,
339	                }
340	            }
341	            Some(_) | None => CandidateLifeSafety::NotUnsafe,
342	        }
343	    }
344	
345	    fn record_mutation(&mut self, payer: PlayerId, before: i32, after: i32, loss_amount: u32) {
346	        let Some(AttemptState::Active {
347	            token,
348	            payer: expected_payer,
349	        }) = self.attempt
350	        else {
351	            return;
352	        };
353	        let Some(committed) = before
354	            .checked_sub(after)
355	            .and_then(|delta| u32::try_from(delta).ok())
356	        else {
357	            self.attempt = Some(AttemptState::Invalid);
358	            return;
359	        };
360	        if expected_payer != payer
361	            || committed == 0
362	            || committed != loss_amount
363	            || self.receipt.is_some()
364	        {
365	            self.attempt = Some(AttemptState::Invalid);
366	            return;
367	        }
368	        self.receipt = Some(LifeMutationReceipt {
369	            token,
370	            payer,
371	            before,
372	            after,
373	            committed,
374	        });
375	        self.attempt = Some(AttemptState::Invalid);
376	    }
377	}
