399	/// CR 701.12c / CR 119.7 + CR 119.8: Apply a simultaneous life-total permutation.
400	///
401	/// `assignment[i] = (receiver, resulting_life)` — each named player's life total
402	/// becomes `resulting_life` by *gaining or losing the difference* from a snapshot
403	/// taken before any mutation (so the permutation is simultaneous and each delta
404	/// is measured against the pre-resolution total, per CR 701.12c). The changes
405	/// route through `apply_life_gain` / `apply_life_loss` — not a raw
406	/// `player.life = ...` set — so replacement effects may modify them and triggered
407	/// abilities (Blood Artist-likes) trigger on the resulting gain/loss.
408	///
409	/// Shared by `ExchangeLifeTotals` (2-slot swap) and `RedistributeLifeTotals`
410	/// (N-slot controller-chosen permutation). Callers that require all-or-nothing
411	/// legality (CR 701.12a exchange) must pre-check before calling; the
412	/// redistribution resolver instead filters illegal receivers out of each
413	/// enumerated option, so every assignment reaching this helper is already legal.
414	pub fn apply_life_totals_assignment(
415	    state: &mut GameState,
416	    assignment: &[(PlayerId, i32)],
417	    completion_player: PlayerId,
418	    completion: Option<PendingEffectResolved>,
419	    events: &mut Vec<GameEvent>,
420	) -> Result<LifeAssignmentOutcome, EffectError> {
421	    // CR 701.12c: snapshot every receiver's current life BEFORE any mutation so
422	    // each delta is measured against the pre-permutation total.
423	    let deltas: Vec<(PlayerId, i32)> = assignment
424	        .iter()
425	        .map(|&(pid, new_life)| {
426	            let old = state
427	                .players
428	                .iter()
429	                .find(|p| p.id == pid)
430	                .map(|p| p.life)
431	                .ok_or(EffectError::PlayerNotFound)?;
432	            Ok((pid, new_life - old))
433	        })
434	        .collect::<Result<Vec<_>, EffectError>>()?;
435	
436	    for (index, (pid, diff)) in deltas.iter().copied().enumerate() {
437	        let deferred = match diff.signum() {
438	            1 => apply_life_gain(state, pid, diff as u32, events).err(),
439	            -1 => apply_life_loss(state, pid, (-diff) as u32, events).err(),
440	            _ => None,
441	        };
442	        if deferred.is_some() {
443	            // CR 616.1: a competing replacement required a player choice; the
444	            // helper installed the WaitingFor and the resume path completes the
445	            // remaining assignments.
446	            state.push_life_total_assignment(PendingLifeTotalAssignment {
447	                completion_player,
448	                remaining: deltas[index + 1..].to_vec(),
449	                completion: completion.clone(),
450	            });
451	            return Ok(LifeAssignmentOutcome::Deferred);
452	        }
453	    }
454	    Ok(LifeAssignmentOutcome::Applied)
455	}
