488	fn complete_pending_life_total_assignment(
489	    state: &mut GameState,
490	    pending: PendingLifeTotalAssignment,
491	    events: &mut Vec<GameEvent>,
492	) {
493	    state.waiting_for = WaitingFor::Priority {
494	        player: pending.completion_player,
495	    };
496	
497	    if let Some(PendingEffectResolved {
498	        kind,
499	        source_id,
500	        resolution_event,
501	        post_actions,
502	        player_action,
503	    }) = pending.completion
504	    {
505	        debug_assert!(
506	            post_actions.is_empty(),
507	            "life-total assignment completion does not support counter post-actions"
508	        );
509	        match resolution_event {
510	            PendingEffectResolutionEvent::Emit => {
511	                events.push(GameEvent::EffectResolved {
512	                    kind,
513	                    source_id,
514	                    subject: None,
515	                });
516	            }
517	            PendingEffectResolutionEvent::Suppress => {}
518	        }
519	        if let Some(action) = player_action {
520	            events.push(GameEvent::PlayerPerformedAction {
521	                player_id: action.player_id,
522	                action: action.action,
523	                look_count: None,
524	                scry_bottom_count: None,
525	                scry_top_count: None,
526	            });
527	        }
528	    }
529	
530	    super::drain_pending_continuation(state, events);
531	}
