533	/// CR 119.3: If an effect causes a player to lose life, adjust their life total.
534	pub fn resolve_lose(
535	    state: &mut GameState,
536	    ability: &ResolvedAbility,
537	    events: &mut Vec<GameEvent>,
538	) -> Result<(), EffectError> {
539	    let (amount, target_filter): (i32, Option<&TargetFilter>) = match &ability.effect {
540	        Effect::LoseLife { amount, target } => (
541	            crate::game::quantity::resolve_quantity_with_targets(state, amount, ability),
542	            target.as_ref(),
543	        ),
544	        _ => return Err(EffectError::MissingParam("LoseLife amount".to_string())),
545	    };
546	
547	    let target_player_id = resolve_life_loss_target(state, ability, target_filter);
548	
549	    if apply_life_loss(state, target_player_id, amount.max(0) as u32, events).is_err() {
550	        return Ok(());
551	    }
552	
553	    events.push(GameEvent::EffectResolved {
554	        kind: EffectKind::from(&ability.effect),
555	        source_id: ability.source_id,
556	        subject: None,
557	    });
558	
559	    Ok(())
560	}
