562	fn resolve_life_loss_target(
563	    state: &GameState,
564	    ability: &ResolvedAbility,
565	    target_filter: Option<&TargetFilter>,
566	) -> PlayerId {
567	    // CR 115.1: When the filter is a context-ref (Controller, etc.) the acting
568	    // player MUST come from state slots — not `ability.targets`, which inherits
569	    // the parent's chosen Player target via chain target propagation. Mirrors
570	    // the Draw/Mill/Discard guard in `resolve_player_for_context_ref`.
571	    if let Some(filter) = target_filter {
572	        if filter.is_context_ref() {
573	            return super::resolve_player_for_context_ref(state, ability, filter);
574	        }
575	    }
576	
577	    // Non-context-ref filters (e.g., explicit Player target on "target opponent
578	    // loses 2 life"): the chosen player is in `ability.targets`.
579	    if let Some(player) = ability.targets.iter().find_map(|target| match target {
580	        TargetRef::Player(player) => Some(*player),
581	        _ => None,
582	    }) {
583	        return player;
584	    }
585	
586	    // No filter and no Player target: defensive fallback to controller (matches
587	    // historical behavior for `LoseLife { target: None }`).
588	    ability.controller
589	}
