591	/// CR 119.5: Set a player's life total to a specific number.
592	///
593	/// Per CR 119.5: "If an effect sets a player's life total to a specific number,
594	/// the player gains or loses the necessary amount of life to end up with the
595	/// new total." The delta is therefore dispatched as either a `LifeGain` or
596	/// `LifeLoss` event through [`apply_life_gain`] / [`apply_life_loss`] so
597	/// the full replacement pipeline fires and the CantGainLife / CantLoseLife
598	/// short-circuits are consistent with every other life-change event.
599	pub fn resolve_set_life_total(
600	    state: &mut GameState,
601	    ability: &ResolvedAbility,
602	    events: &mut Vec<GameEvent>,
603	) -> Result<(), EffectError> {
604	    let (amount_expr, target) = match &ability.effect {
605	        Effect::SetLifeTotal { amount, target } => (amount, target),
606	        _ => return Err(EffectError::MissingParam("SetLifeTotal amount".to_string())),
607	    };
608	    // CR 119.5 + CR 608.2f: Resolve which players' life totals are set. The
609	    // common single-player forms ("your" → Controller, "target player's" →
610	    // the chosen target) preserve the original single-player behavior. The
611	    // non-targeted all-players form ("each player's life total becomes N" —
612	    // Worldfire, issue #2882) expands to every player in APNAP order.
613	    let target_player_ids: Vec<PlayerId> = if matches!(target, TargetFilter::AllPlayers) {
614	        crate::game::players::apnap_order(state)
615	    } else {
616	        vec![ability
617	            .targets
618	            .iter()
619	            .find_map(|t| {
620	                if let TargetRef::Player(pid) = t {
621	                    Some(*pid)
622	                } else {
623	                    None
624	                }
625	            })
626	            .unwrap_or(ability.controller)]
627	    };
628	
629	    // CR 119.5: Set each player's life total one at a time, decomposing into the
630	    // matching gain/loss event. apply_life_gain / apply_life_loss each
631	    // handle their own CR 119.7 / CR 119.8 short-circuits and replacement
632	    // pipeline routing.
633	    for target_player_id in target_player_ids {
634	        // CR 119.5 + CR 109.5: Resolve the new life total per player so a
635	        // third-person "the number of [X] THEY control" count (Biorhythm,
636	        // Shaman of Forgotten Ways) binds to each recipient. `scoped_player` is
637	        // rebound to the player whose life total is being set; the count's
638	        // `ScopedPlayer` controller reads it, while `original_controller` (and
639	        // hence any `You`-scoped count) and the ability's targets / chosen_x
640	        // stay fixed to the caster. Single-player and caster-scoped forms
641	        // ("becomes 10", "your life total", Repay in Kind's cross-player
642	        // extremum) are unaffected — they carry no `ScopedPlayer` ref to vary.
643	        let mut scoped_ability = ability.clone();
644	        scoped_ability.set_scoped_player_recursive(target_player_id);
645	        let amount = crate::game::quantity::resolve_quantity_with_targets(
646	            state,
647	            amount_expr,
648	            &scoped_ability,
649	        );
650	
651	        // CR 810.9a: "If a cost or effect needs to know the value of an
652	        // individual player's life total, that cost or effect uses the
653	        // team's life total instead" — degenerates to `Player::life` outside
654	        // team-based formats. CR 810.9c: the diff is still applied to only
655	        // `target_player_id`'s own life, so the team total moves by exactly
656	        // the gained/lost amount.
657	        if !state.players.iter().any(|p| p.id == target_player_id) {
658	            return Err(EffectError::PlayerNotFound);
659	        }
660	        let current_life = crate::game::players::team_life_total(state, target_player_id);
661	        let diff = amount - current_life;
662	
663	        let deferred = match diff.signum() {
664	            1 => apply_life_gain(state, target_player_id, diff as u32, events).err(),
665	            -1 => apply_life_loss(state, target_player_id, (-diff) as u32, events).err(),
666	            _ => None,
667	        };
668	        if deferred.is_some() {
669	            // CR 616.1: A competing replacement required a player choice; the
670	            // helper already installed the WaitingFor state. Return without
671	            // emitting EffectResolved — the resume path completes resolution.
672	            // (A multi-player set that hits a replacement mid-list defers from
673	            // that player onward, mirroring the original single-player path.)
674	            return Ok(());
675	        }
676	    }
677	
678	    events.push(GameEvent::EffectResolved {
679	        kind: EffectKind::from(&ability.effect),
680	        source_id: ability.source_id,
681	        subject: None,
682	    });
683	
684	    Ok(())
685	}
