178	/// CR 118.3 + CR 119.4b + CR 601.2h + CR 602.2b: Can this player pay `amount`
179	/// life specifically as a spell-casting or activation cost?
180	pub fn can_pay_life_cast_or_activation_cost(

  1	use crate::game::effects::life::{apply_life_gain, apply_life_loss};
  2	use crate::game::static_abilities::{player_has_cant_gain_life, player_has_cant_lose_life};
  3	use crate::types::ability::{
  4	    ContinuousModification, Duration, Effect, EffectError, EffectKind, PtStat, ResolvedAbility,
  5	    TargetFilter, TargetRef,
  6	};
  7	use crate::types::events::GameEvent;
  8	use crate::types::game_state::GameState;
  9	
 10	/// CR 701.12g: Exchange a player's life total with the source permanent's power
 11	/// or toughness (Tree of Perdition, Tree of Redemption, Evra, Halcyon Witness).
 12	///
 13	/// CR 701.12g: each value becomes equal to the previous value of the other, so
 14	/// both previous values must be read before either changes. When a life total
 15	/// is involved the player gains or loses the amount of life necessary to reach
 16	/// the other value (it is a gain/loss, not a set), and the exchange is
 17	/// all-or-nothing: if the life change is forbidden (CR 119.7 can't-gain when
 18	/// raising, CR 119.8 can't-lose when lowering), no part of the exchange occurs.
 19	///
 20	/// The stat side becomes an indefinite layer-7b continuous "set" effect
 21	/// (CR 613.4b) on the source: its base power/toughness is set to the player's
 22	/// previous life total, so counters and +N/+N modifiers (both CR 613.4c) still
 23	/// apply on top per the card's rulings.
 24	pub fn resolve(
 25	    state: &mut GameState,
 26	    ability: &ResolvedAbility,
 27	    events: &mut Vec<GameEvent>,
 28	) -> Result<(), EffectError> {
 29	    let stat = match &ability.effect {
 30	        Effect::ExchangeLifeWithStat { stat, .. } => *stat,
 31	        // Dispatcher in effects/mod.rs only routes ExchangeLifeWithStat here.
 32	        _ => return Ok(()),
 33	    };
 34	
 35	    let resolved_kind = EffectKind::from(&ability.effect);
 36	
 37	    // "your life total" forms declare no player target and fall back to the
 38	    // ability's controller; "target opponent's life total" supplies a player.
 39	    let player_id = ability
 40	        .targets
 41	        .iter()
 42	        .find_map(|t| match t {
 43	            TargetRef::Player(pid) => Some(*pid),
 44	            TargetRef::Object(_) => None,
 45	        })
 46	        .unwrap_or(ability.controller);
 47	
 48	    // CR 701.12a: capture both previous values before any mutation.
 49	    let Some(source) = state.objects.get(&ability.source_id) else {
 50	        // Source left the battlefield before resolution — the stat side can't
 51	        // be completed, so per CR 701.12a nothing happens.
 52	        events.push(GameEvent::EffectResolved {
 53	            kind: resolved_kind,
 54	            source_id: ability.source_id,
 55	            subject: None,
 56	        });
 57	        return Ok(());
 58	    };
 59	    let stat_value = match stat {
 60	        PtStat::Power => source.power,
 61	        PtStat::Toughness => source.toughness,
 62	        PtStat::TotalPowerToughness => {
 63	            return Err(EffectError::InvalidParam(
 64	                "total power and toughness is not exchangeable as a single stat".to_string(),
 65	            ));
 66	        }
 67	    };
 68	    let Some(stat_value) = stat_value else {
 69	        // Source has no power/toughness (not a creature) — can't complete.
 70	        events.push(GameEvent::EffectResolved {
 71	            kind: resolved_kind,
 72	            source_id: ability.source_id,
 73	            subject: None,
 74	        });
 75	        return Ok(());
 76	    };
 77	
 78	    let old_life = state
 79	        .players
 80	        .iter()
 81	        .find(|p| p.id == player_id)
 82	        .ok_or(EffectError::PlayerNotFound)?
 83	        .life;
 84	
 85	    // CR 701.12g + CR 119.7 / CR 119.8: All-or-nothing. The player would gain or
 86	    // lose life to reach `stat_value`. If that change is forbidden (can't-gain
 87	    // when raising, can't-lose when lowering), no part of the exchange occurs.
 88	    let life_blocked = match stat_value.cmp(&old_life) {
 89	        std::cmp::Ordering::Greater => player_has_cant_gain_life(state, player_id),
 90	        std::cmp::Ordering::Less => player_has_cant_lose_life(state, player_id),
 91	        std::cmp::Ordering::Equal => false,
 92	    };
 93	    if life_blocked {
 94	        events.push(GameEvent::EffectResolved {
 95	            kind: resolved_kind,
 96	            source_id: ability.source_id,
 97	            subject: None,
 98	        });
 99	        return Ok(());
100	    }
101	
102	    // CR 613.4b: Set the source's exchanged stat to the player's previous life
103	    // total via an indefinite (Duration::Permanent) layer-7b continuous effect.
104	    let modification = match stat {
105	        PtStat::Power => ContinuousModification::SetPower { value: old_life },
106	        PtStat::Toughness => ContinuousModification::SetToughness { value: old_life },
107	        PtStat::TotalPowerToughness => {
108	            return Err(EffectError::InvalidParam(
109	                "total power and toughness is not exchangeable as a single stat".to_string(),
110	            ));
111	        }
112	    };
113	    state.add_transient_continuous_effect(
114	        ability.source_id,
115	        ability.controller,
116	        Duration::Permanent,
117	        TargetFilter::SpecificObject {
118	            id: ability.source_id,
119	        },
120	        vec![modification],
121	        None,
122	    );
123	
124	    // CR 701.12g: the player gains or loses the difference to reach the stat's
125	    // previous value (a gain/loss, not a set). The helpers re-check CR
126	    // 119.7/119.8 and route through the replacement pipeline.
127	    let diff = stat_value - old_life;
128	    let deferred = match diff.signum() {
129	        1 => apply_life_gain(state, player_id, diff as u32, events).err(),
130	        -1 => apply_life_loss(state, player_id, (-diff) as u32, events).err(),
131	        _ => None,
132	    };
133	    if deferred.is_some() {
134	        // CR 614.7: a competing replacement required a player choice; the helper
135	        // installed the WaitingFor and the resume path completes resolution.
136	        return Ok(());
137	    }
138	
139	    events.push(GameEvent::EffectResolved {
140	        kind: resolved_kind,
141	        source_id: ability.source_id,
142	        subject: None,
143	    });
144	    Ok(())
145	}
