444	/// CR 106.4 + CR 703.4q: Apply the final replacement-ordered mana dispositions
445	/// as the step or phase ends, then apply one aggregate Yurlok-class life-loss
446	/// event for the mana units that were actually removed. Retained or transformed
447	/// units are not lost and therefore do not contribute.
448	pub(super) fn apply_empty_mana_pool_event(
449	    state: &mut GameState,
450	    event: ProposedEvent,
451	    events: &mut Vec<GameEvent>,
452	) -> EmptyManaPoolApplyOutcome {
453	    let ProposedEvent::EmptyManaPool {
454	        player_id, units, ..
455	    } = event
456	    else {
457	        debug_assert!(false, "expected EmptyManaPool event");
458	        return EmptyManaPoolApplyOutcome::Applied;
459	    };
460	
461	    // CR 604.1: This is an existence query, evaluated exactly once for this
462	    // player's aggregate empty-pool event.
463	    let causes_life_loss =
464	        crate::game::static_abilities::player_unspent_mana_loss_causes_life_loss(state, player_id);
465	    let amount =
466	        crate::types::mana::apply_empty_mana_pool_decisions(state, player_id, &units, events);
467	    state.pending_step_end_mana_handlers.clear();
468	
469	    if !causes_life_loss || amount == 0 {
470	        return EmptyManaPoolApplyOutcome::Applied;
471	    }
472	
473	    match crate::game::effects::life::apply_life_loss(state, player_id, amount, events) {
474	        Ok(_) => EmptyManaPoolApplyOutcome::Applied,
475	        Err(crate::game::effects::life::ReplacementDeferred::ReplacementChoice) => {
476	            EmptyManaPoolApplyOutcome::Deferred
477	        }
478	        Err(crate::game::effects::life::ReplacementDeferred::SubstitutionContinuation) => {
479	            mark_phase_transition_awaiting_post_replacement(state);
480	            EmptyManaPoolApplyOutcome::Deferred
481	        }
482	    }
483	}
