700	    // hit on a 2-toughness creature would mark 4 on the creature AND deal 2 to the
701	    // controller (6 total); the rules-correct outcome is 2 marked + 2 redirected
702	    // (4 total). Reduce the primary hit to the lethal portion for the creature's
703	    // marked damage, DamageDealt event, and damage record; lifelink and the return
704	    // value keep `actual_amount` because the total damage dealt is unchanged.
705	    // CR 120.4a "that creature's controller": the rider only redirects when the
706	    // damaged permanent is a creature (real class cards all read "target creature").
707	    let redirect_excess = if is_creature
708	        && matches!(
709	            (ctx.excess_recipient, &t),
710	            (
711	                Some(ExcessRecipient::TargetController {
712	                    source_keyword: None
713	                }),
714	                TargetRef::Object(_)
715	            )
716	        ) {
717	        excess
718	    } else {
719	        0
720	    };
721	    let primary_amount = actual_amount.saturating_sub(redirect_excess);
722	    // CR 120.4a: when the excess is redirected, the creature was dealt only its
723	    // lethal portion — it was NOT "dealt excess damage" (the excess went to its
724	    // controller instead). Report zero excess on the creature's event and record
725	    // so "was dealt excess damage" triggers (Maarika, Rith, Aegar, …) do not
726	    // fire on the creature. Without a rider `redirect_excess == 0`, so this is the
727	    // normal computed `excess` (e.g. plain overkill still reports its excess).
728	    let primary_excess = excess.saturating_sub(redirect_excess);
729	    if redirect_excess > 0 {
730	        if let TargetRef::Object(obj_id) = &t {
731	            // Only the marked-damage path over-marks above; wither/infect deal
732	            // -1/-1 counters instead (no excess-redirect card uses them).
733	            if !ctx.has_wither && !ctx.has_infect {
734	                if let Some(o) = state.objects.get_mut(obj_id) {
735	                    o.damage_marked = o.damage_marked.saturating_sub(redirect_excess);
736	                }
737	            }
738	        }
739	    }
740	
741	    events.push(GameEvent::DamageDealt {
742	        source_id: ctx.source_id,
743	        target: t.clone(),
744	        amount: primary_amount,
745	        is_combat,
746	        excess: primary_excess,
747	    });
748	
749	    // CR 120.1: Record damage for "was dealt damage by" condition queries.
750	    if actual_amount > 0 {
751	        let target_controller = match t {
752	            TargetRef::Player(player_id) => *player_id,
753	            TargetRef::Object(object_id) => state
754	                .objects
755	                .get(object_id)
756	                .map(|object| object.controller)
757	                .unwrap_or(ctx.controller),
758	        };
759	        // CR 400.7: Snapshot the target's incarnation at damage time so
760	        // subsequent zone-change look-backs do not match a new incarnation.
761	        let target_incarnation = match t {
762	            TargetRef::Object(object_id) => state
763	                .objects
764	                .get(object_id)
765	                .map(|object| object.incarnation),
766	            TargetRef::Player(_) => None,
767	        };
768	        // CR 608.2i + CR 608.2h: Snapshot the damage source's characteristics at
769	        // damage time so look-back source-filter queries ("opponents who were
770	        // dealt combat damage by ~ or a Dragon this turn") evaluate against the
771	        // source as it was when the damage was dealt — the source may later
772	        // change type, leave the battlefield (CR 113.7a LKI), or be removed.
773	        let src = state.objects.get(&ctx.source_id);
774	        // CR 400.7: Use the incarnation captured with the damage context, not
775	        // a post-application live lookup. The latter can name a later object
776	        // after a replacement pause or zone change.
777	        let source_incarnation = ctx.source_incarnation;
778	        let mut record = DamageRecord {
779	            source_id: ctx.source_id,
780	            source_controller: ctx.controller,
781	            target: t.clone(),
782	            target_controller,
783	            target_incarnation,
784	            source_incarnation,
785	            // CR 120.4a: the permanent was dealt only the lethal portion; the
786	            // excess is recorded against the controller by the redirect below.
787	            amount: primary_amount,
788	            is_combat,
789	            // CR 120.10: Record excess so "was dealt excess damage this turn"
790	            // intervening-if conditions can query without re-computing lethal.
791	            // Redirected excess is recorded against the controller by the redirect
792	            // leg below, so the creature's record reports `primary_excess` (zero
793	            // when the rider redirected it).
794	            excess: primary_excess,
795	            // CR 608.2i + CR 608.2h: the obj-derived source snapshot below
796	            // overwrites these when the source still exists; the empty/default
797	            // tail (Default::default()) covers the source-already-gone case.
798	            source_controller_snapshot: ctx.controller,
799	            source_owner: ctx.controller,
800	            ..Default::default()
801	        };
