804	            record.source_core_types = obj.card_types.core_types.clone();
805	            record.source_subtypes = obj.card_types.subtypes.clone();
806	            record.source_supertypes = obj.card_types.supertypes.clone();
807	            record.source_keywords = obj.keywords.clone();
808	            record.source_power = obj.power;
809	            record.source_toughness = obj.toughness;
810	            // CR 202.3d + CR 702.102b: snapshot the source's colors / mana value
811	            // through the split-aware authority so a FUSED split spell freezes its
812	            // COMBINED colors and mana value for damage-history source filters. For
813	            // permanents and non-fused spells these are byte-identical to the prior
814	            // `obj.color` / `mana_value_with_x(zone, cost_x_paid)` reads (CR 202.3e:
815	            // the non-fused mana-value arm includes the chosen X).
816	            record.source_colors = obj.spell_colors();
817	            record.source_mana_value = obj.spell_mana_value();
818	            record.source_controller_snapshot = obj.controller;
819	            record.source_owner = obj.owner;
820	            // CR 608.2i: snapshot the source's zone (Stack for a spell,
821	            // Battlefield for a permanent) so a zone-discriminating look-back
822	            // source filter evaluates against the zone as it was at damage time.
823	            record.source_zone = obj.zone;
824	        }
825	        state.damage_dealt_this_turn.push_back(record);
826	        // CR 120.3 + CR 120.6 + CR 702.11b + CR 613.1f: Mark the source as having
827	        // actually dealt damage (this branch is gated on `actual_amount > 0`, i.e.
828	        // a nonzero amount actually dealt per CR 120.3/120.6, not the would-be
829	        // amount of CR 120.1a). Only battlefield-resident sources carry this
830	        // sticky flag, since the reset in `apply_zone_exit_cleanup` is gated on a
831	        // battlefield exit. When the id is NEWLY inserted, mark layers fully dirty
832	        // so `flush_layers` recomputes the materialized keyword set that
833	        // `has_hexproof` reads — otherwise the conditional hexproof grant for
834	        // "has hexproof if it hasn't dealt damage yet" would never drop at the
835	        // targeting check (a Clean `layers_dirty` no-ops `flush_layers`).
836	        if state
837	            .objects
838	            .get(&ctx.source_id)
839	            .is_some_and(|obj| obj.zone == crate::types::zones::Zone::Battlefield)
