846	    // CR 120.4a treats the redirect as ONE modified damage event. The excess is
847	    // dealt to the controller by a redirect leg that carries `lifelink_bonus` (this
848	    // creature's lethal `primary_amount`) plus the source's real lifelink, so THAT
849	    // leg gains the COMBINED lifelink (its own dealt + the bonus) when it resolves —
850	    // inline OR after its own replacement pause+resume (the bonus is threaded through
851	    // the snapshot / PendingReplacement). `redirected` records that the excess and
852	    // this leg's lifelink were handed off, so the creature leg gains nothing here.
853	    let mut redirected = false;
854	    if let (
855	        Some(ExcessRecipient::TargetController {
856	            source_keyword: None,
857	        }),
858	        TargetRef::Object(obj_id),
859	    ) = (ctx.excess_recipient, t)
860	    {
861	        if redirect_excess > 0 {
862	            if let Some(controller) = state.objects.get(obj_id).map(|o| o.controller) {
863	                // CR 120.7: same source object as the primary damage (source_id /
864	                // controller / keywords reused). `excess_recipient: None` is a
865	                // re-entrancy guard; `lifelink_bonus: primary_amount` hands this
866	                // creature leg's lethal to the redirect leg so the combined lifelink
867	                // is gained even if the redirected damage itself pauses on a
868	                // replacement choice.
869	                let redirect_ctx = DamageContext {
870	                    excess_recipient: None,
871	                    lifelink_bonus: primary_amount,
872	                    ..*ctx
873	                };
874	                redirected = true;
875	                // Route through the same non-combat single-target pipeline the
876	                // primary player-damage path uses (gate + CR 614/615 replacement).
877	                // A pause here propagates NeedsChoice; the redirect leg carries
878	                // `lifelink_bonus`, so the combined lifelink is still gained on resume.
879	                match apply_damage_to_target(
880	                    state,
881	                    &redirect_ctx,
882	                    TargetRef::Player(controller),
883	                    redirect_excess,
884	                    false,
885	                    events,
886	                ) {
887	                    // The redirect leg gains the combined lifelink (its own dealt +
888	                    // the bonus) itself — but ONLY when it actually reaches its
889	                    // lifelink path by dealing damage. A fully prevented, gated, or
890	                    // phased redirect returns `Applied(0)` from the prevention/early
891	                    // paths BEFORE that gain, so fall through to have the creature leg
892	                    // gain lifelink for the lethal `primary_amount` it did deal.
893	                    Ok(DamageResult::Applied(0)) => redirected = false,
894	                    Ok(DamageResult::Applied(_)) => {}
895	                    Ok(DamageResult::NeedsChoice) => return DamageResult::NeedsChoice,
896	                    // A redirect gate failure must not corrupt the primary result;
897	                    // fall through so the source still gains lifelink for the lethal
898	                    // portion it actually dealt (the excess was simply not redirected).
899	                    Err(_) => redirected = false,
900	                }
901	            }
902	        }
903	    }
904	
905	    // CR 702.15b / CR 120.3f: Lifelink — the source's controller gains life for the
906	    // damage THIS leg actually dealt (`primary_amount`, the lethal portion after any
907	    // rider reduction) plus any `lifelink_bonus` deferred from an earlier leg of the
908	    // same CR 120.4a-modified event. Skipped when the excess and this leg's lifelink
909	    // were handed to the redirect leg (which gains the combined total instead). For a
910	    // redirect leg this fires with `primary_amount` = the excess it dealt and
911	    // `lifelink_bonus` = the creature's lethal, so it gains the combined total —
912	    // inline or on resume; a prevented redirect leg deals 0 and gains only the
913	    // deferred lethal bonus. Without the rider `lifelink_bonus == 0`, the ordinary
914	    // gain.
915	    if !redirected {
916	        let lifelink_amount = primary_amount + ctx.lifelink_bonus;
917	        if ctx.has_lifelink
918	            && lifelink_amount > 0
919	            && super::life::apply_life_gain(state, ctx.controller, lifelink_amount, events).is_err()
920	        {
921	            // CR 616.1: two or more co-applicable life-gain replacements — the gaining
922	            // player must choose which applies first. All damage has
923	            // already been dealt; only this final lifelink gain is deferred.
924	            return DamageResult::NeedsChoice;
925	        }
926	    }
927	
928	    DamageResult::Applied(actual_amount)
929	}
