 23	fn make_artifact(runner: &mut GameRunner, id: ObjectId) {
 24	    let object = runner.state_mut().objects.get_mut(&id).unwrap();
 25	    object.card_types.core_types = vec![CoreType::Artifact];
 26	    object.base_card_types = object.card_types.clone();
 27	    object.power = None;
 28	    object.toughness = None;
 29	    object.base_power = None;
 30	    object.base_toughness = None;
