 33	fn activated_signet_states() -> (GameState, GameState, ObjectId) {
 34	    let mut scenario = GameScenario::new_n_player(2, 7);
 35	    scenario.at_phase(Phase::PreCombatMain);
 36	    scenario.add_basic_land(P0, ManaColor::White);
 37	    let signet = scenario
 38	        .add_creature_from_oracle(P0, "Dimir Signet", 0, 0, DIMIR_SIGNET_ORACLE)
 39	        .id();
 40	
 41	    let mut runner = scenario.build();
 42	    make_artifact(&mut runner, signet);
 43	    let pre_state = runner.state().clone();
 44	    runner
 45	        .act(GameAction::ActivateAbility {
 46	            source_id: signet,
 47	            ability_index: 0,
 48	        })
 49	        .expect("the real Signet mana ability must activate");
 50	    (pre_state, runner.state().clone(), signet)
 51	}
