153	/// The real activation inserts the auto-tapped land's exact pip, spends it for
154	/// the Signet, then inserts the two produced pips. Reapplying the recorded
155	/// commands in entry order must reproduce that pool and its pip high-water.
156	#[test]
157	fn real_mana_activation_replays_recorded_insert_and_spend_commands() {
158	    let (pre_state, ordinary_state, signet) = activated_signet_states();
159	    let commands = semantic_commands(&ordinary_state);
160	
161	    assert!(
162	        commands
163	            .iter()
164	            .any(|command| matches!(command, ResolvedRulesCommand::ManaInsert(_))),
165	        "the ordinary activation must journal exact insert commands"
166	    );
167	    assert!(
168	        commands
169	            .iter()
170	            .any(|command| matches!(command, ResolvedRulesCommand::ManaSpend(_))),
171	        "the ordinary activation must journal its exact solver-selected payment"
172	    );
