 58	    /// Returns whether `attacks` is exactly the declaration this witness replayed.
 59	    ///
 60	    /// The bounded witness only certifies attacks at one player, so retaining the
 61	    /// ordered `(attacker incarnation, player target)` pairs is sufficient to
 62	    /// reject later unions, removals, reordering, or planeswalker redirection.
 63	    pub fn binds_declaration(
 64	        &self,
 65	        state: &GameState,
 66	        attacks: &[(crate::types::identifiers::ObjectId, AttackTarget)],
 67	    ) -> bool {
 68	        self.declaration.len() == attacks.len()
 69	            && self.declaration.iter().zip(attacks).all(
 70	                |((attacker, defending_player), (attacker_id, target))| {
 71	                    state.objects.get(attacker_id).is_some_and(|object| {
 72	                        ObjectIncarnationRef::from_object(object) == *attacker
 73	                    }) && *defending_player == self.defending_player
 74	                        && *target == AttackTarget::Player(*defending_player)
 75	                },
